1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type QuoteResult = {
23	  premium: number;
24	};
25	
26	export type ScenarioResults = {
27	  results: QuoteResult[];
28	};
29	
30	const PROCESSING_FEE = 5;
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	// Charged on every quote, unconditionally — it is the cost of assessing the
42	// items, not a penalty for being a new customer. Named "first insurance" in
43	// some of the domain material, which misleads: it does not depend on customer
44	// history or on the quote's position in the scenario.
45	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / 100;
49	
50	const itemBasePremium = (item: Item): number =>
51	  BASE_PREMIUM_BY_TYPE[item.type];
52	
53	const BLOCK_SIZE = 3;
54	
55	const BLOCK_PREMIUM = 60;
56	
57	const sumOf = (amounts: number[]): number =>
58	  amounts.reduce((sum, amount) => sum + amount, 0);
59	
60	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
61	
62	const sumOfItemBasePremiums = (items: Item[]): number =>
63	  sumOf(items.map(itemBasePremium));
64	
65	const groupByType = (items: Item[]): Item[][] => {
66	  const types = new Set(items.map((item) => item.type));
67	
68	  return [...types].map((type) => items.filter((item) => item.type === type));
69	};
70	
71	const alikeGroupBasePremium = (items: Item[]): number =>
72	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  sumOf(groupByType(items).map(alikeGroupBasePremium));
76	
77	const roundPremiumInMHPCOsFavor = (amount: number): number =>
78	  Math.ceil(amount);
79	
80	// The inputs a single quote is computed from: `items` drives the base premium
81	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
82	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
83	// general — a claim step is not a contract and must not trigger the follow-up
84	// discount.
85	type QuoteRequest = {
86	  customer: Customer;
87	  items: Item[];
88	  precedingQuoteCount: number;
89	};
90	
91	const LOYALTY_YEARS = 2;
92	
93	const LOYALTY_DISCOUNT_PERCENT = 20;
94	
95	// Modifier percents are signed so surcharges and discounts can be summed
96	// uniformly; a discount enters the sum as its negation.
97	const asDiscount = (percent: number): number => -percent;
98	
99	const isLoyal = (customer: Customer): boolean =>
100	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
101	
102	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
103	
104	// Policy-wide modifiers do NOT compound: each is an independent percentage of
105	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
106	// would give a different, wrong answer.
107	const isFollowUpContract = (request: QuoteRequest): boolean =>
108	  request.precedingQuoteCount > 0;
109	
110	const policyModifierPercents = (request: QuoteRequest): number[] => [
111	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
112	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
113	  ...(isFollowUpContract(request)
114	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
115	    : []),
116	];
117	
118	const applyPolicyModifiers = (
119	  basePremium: number,
120	  request: QuoteRequest,
121	): number =>
122	  basePremium +
123	  sumOf(
124	    policyModifierPercents(request).map((percent) =>
125	      percentOf(basePremium, percent),
126	    ),
127	  );
128	
129	const CURSE_SURCHARGE_PERCENT = 50;
130	
131	const HIGH_ENCHANTMENT_LEVEL = 5;
132	
133	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
134	
135	const isHighlyEnchanted = (item: Item): boolean =>
136	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
137	
138	const isCursed = (item: Item): boolean => item.cursed === true;
139	
140	type ItemSurchargeRule = {
141	  applies: (item: Item) => boolean;
142	  percent: number;
143	};
144	
145	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
146	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
147	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
148	];
149	
150	// Item-scoped surcharges are charged on the item's own base premium, so they
151	// must NOT go through applyPolicyModifiers.
152	const itemSurcharges = (item: Item): number =>
153	  sumOf(
154	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
155	      percentOf(itemBasePremium(item), rule.percent),
156	    ),
157	  );
158	
159	const policyItemSurcharges = (items: Item[]): number =>
160	  sumOf(items.map(itemSurcharges));
161	
162	const quotePremium = (request: QuoteRequest): number =>
163	  roundPremiumInMHPCOsFavor(
164	    applyPolicyModifiers(policyBasePremium(request.items), request) +
165	      policyItemSurcharges(request.items) +
166	      PROCESSING_FEE,
167	  );
168	
169	const isQuote = (step: Step): boolean => step.op === "quote";
170	
171	// What the scenario has accumulated so far. Steps are folded rather than mapped
172	// because a step's result depends on the steps before it: `precedingQuoteCount`
173	// drives the follow-up discount today, and claim steps will thread a remaining
174	// cap through the same carry.
175	type ScenarioState = {
176	  results: QuoteResult[];
177	  precedingQuoteCount: number;
178	};
179	
180	const INITIAL_STATE: ScenarioState = { results: [], precedingQuoteCount: 0 };
181	
182	// The customer is scenario-wide, so it is closed over rather than threaded
183	// through the fold alongside the per-step state.
184	const stepRunnerFor =
185	  (customer: Customer) =>
186	  (state: ScenarioState, step: Step): ScenarioState => ({
187	    results: [
188	      ...state.results,
189	      {
190	        premium: quotePremium({
191	          customer,
192	          items: step.items ?? [],
193	          precedingQuoteCount: state.precedingQuoteCount,
194	        }),
195	      },
196	    ],
197	    precedingQuoteCount: state.precedingQuoteCount + (isQuote(step) ? 1 : 0),
198	  });
199	
200	export const runScenario = (scenario: Scenario): ScenarioResults => ({
201	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
202	    .results,
203	});
