const isQuote = (step: Step): boolean => step.op === "quote";

// What the scenario has accumulated so far. Steps are folded rather than mapped
// because a step's result depends on the steps before it: `precedingQuoteCount`
// drives the follow-up discount today, and claim steps will thread a remaining
// cap through the same carry.
type ScenarioState = {
  results: StepResult[];
  precedingQuoteCount: number;
};

const INITIAL_STATE: ScenarioState = { results: [], precedingQuoteCount: 0 };

// Running a step is a state transition: it reads the carry accumulated by the
// preceding steps and returns the next carry. Every step kind gets its own
// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
// will be added without touching the quote path.
type StepRunner = (
  customer: Customer,
  state: ScenarioState,
  step: Step,
) => ScenarioState;

const appendResult = (
  state: ScenarioState,
  result: StepResult,
): ScenarioState => ({ ...state, results: [...state.results, result] });

const runQuoteStep: StepRunner = (customer, state, step) => ({
  ...appendResult(state, {
    premium: quotePremium({
      customer,
      items: step.items ?? [],
      precedingQuoteCount: state.precedingQuoteCount,
    }),
  }),
  precedingQuoteCount: state.precedingQuoteCount + 1,
});

const runStep: StepRunner = (customer, state, step) =>
  isQuote(step) ? runQuoteStep(customer, state, step) : state;

// The customer is scenario-wide, so it is closed over rather than threaded
// through the fold alongside the per-step state.
const stepRunnerFor =
  (customer: Customer) =>
  (state: ScenarioState, step: Step): ScenarioState =>
    runStep(customer, state, step);

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
    .results,
});

